16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	
20	import org.springframework.samples.petclinic.model.Sha256;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Derives a household's stable, shared identifier from its last name and postcode.
25	 *
26	 * <p>Owners belong to the same household when they share a last name (compared
27	 * case-insensitively and ignoring differences in surrounding or repeated whitespace)
28	 * and postcode. Because the identifier is a deterministic hash of that normalized
29	 * identity, every owner in a household maps to the same value automatically,
30	 * independently and across requests, without any owner having to opt in.
31	 */
32	@Component
33	public class HouseholdIdGenerator {
34	
35	    private static final int ID_LENGTH = 12;
36	
37	    /**
38	     * Build the shared household identifier for the household identified by the given
39	     * last name and postcode: the first {@value #ID_LENGTH} hex characters of the
40	     * SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
41	     *
42	     * <p>An owner without a postcode belongs to no shared household, so this returns
43	     * {@code null} in that case.
44	     *
45	     * @param lastName the household's last name
46	     * @param postcode the household's postcode
47	     * @return the stable household identifier, e.g. {@code "0a1b2c3d4e5f"}, or
48	     * {@code null} when no postcode is supplied
49	     */
50	    public String generate(String lastName, String postcode) {
51	        if (postcode == null || postcode.isBlank()) {
52	            return null;
53	        }
54	        String identity = normalize(lastName) + "|" + postcode;
55	        return Sha256.hex(identity).substring(0, ID_LENGTH);
56	    }
57	
58	    /**
59	     * Normalize the last name for comparison: trim, collapse each run of whitespace to
60	     * a single space and lower-case, so that differences in case or spacing do not
61	     * split what is really one household.
62	     */
63	    private static String normalize(String value) {
64	        if (value == null) {
65	            return "";
66	        }
67	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
68	    }
69	}
