16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	import java.util.function.Predicate;
20	
21	import org.springframework.samples.petclinic.model.MemberId;
22	import org.springframework.samples.petclinic.model.Sha256;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Builds an owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} (see
27	 * {@link MemberId}) where REGION is the owner's canonical region (see
28	 * {@link org.springframework.samples.petclinic.model.RegionResolver}), FY is the two-digit
29	 * fiscal year, HASH8 is the first eight upper-case hexadecimal characters of the SHA-256
30	 * hash over the owner's normalized telephone followed by its last name, and CHK is the
31	 * member id's Luhn check digit. The identity is derived purely from the owner's own fields,
32	 * carrying no sequence number.
33	 */
34	@Component
35	public class MemberIdGenerator {
36	
37	    private static final int HASH_LENGTH = 8;
38	
39	    /**
40	     * Build the member id for a new owner.
41	     *
42	     * @param region              the owner's canonical region
43	     * @param fiscalYearShort     the two-digit fiscal year of the owner's registration date
44	     * @param normalizedTelephone the owner's normalized (E.164) telephone
45	     * @param lastName            the owner's last name
46	     * @return the formatted member id, e.g. {@code "NSW261A2B3C4D5"}
47	     */
48	    public String generate(String region, int fiscalYearShort, String normalizedTelephone, String lastName) {
49	        return MemberId.format(region, fiscalYearShort, hash8(normalizedTelephone, lastName));
50	    }
51	
52	    /**
53	     * Build a member id that does not collide with any already in use. The id is derived
54	     * exactly as {@link #generate(String, int, String, String)}; when that value is already
55	     * taken, {@code '-<n>'} is appended with the smallest {@code n} of two or more that
56	     * yields an unused id.
57	     *
58	     * @param region              the owner's canonical region
59	     * @param fiscalYearShort     the two-digit fiscal year of the owner's registration date
60	     * @param normalizedTelephone the owner's normalized (E.164) telephone
61	     * @param lastName            the owner's last name
62	     * @param isTaken             tests whether a candidate id is already in use
63	     * @return a member id not reported as taken by {@code isTaken}
64	     */
65	    public String generateUnique(String region, int fiscalYearShort, String normalizedTelephone, String lastName,
66	            Predicate<String> isTaken) {
67	        String base = generate(region, fiscalYearShort, normalizedTelephone, lastName);
68	        String candidate = base;
69	        for (int n = 2; isTaken.test(candidate); n++) {
70	            candidate = base + "-" + n;
71	        }
72	        return candidate;
73	    }
74	
75	    private String hash8(String normalizedTelephone, String lastName) {
76	        String identity = safe(normalizedTelephone) + safe(lastName);
77	        return Sha256.hex(identity).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
78	    }
79	
80	    private String safe(String value) {
81	        return value == null ? "" : value;
82	    }
83	}
