16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.concurrent.atomic.AtomicLong;
19	
20	import org.slf4j.Logger;
21	import org.slf4j.LoggerFactory;
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.stereotype.Component;
24	
25	import tools.jackson.databind.ObjectMapper;
26	
27	/**
28	 * Emits audit-trail entries for owner lifecycle events to the dedicated {@code AUDIT}
29	 * logger, keeping audit side-effects out of the request-handling and persistence code.
30	 */
31	@Component
32	public class OwnerAuditLogger {
33	
34	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
35	
36	    private final ObjectMapper objectMapper = new ObjectMapper();
37	
38	    /** Monotonically increasing sequence stamped on each create event. */
39	    private final AtomicLong sequence = new AtomicLong();
40	
41	    /**
42	     * Record the successful registration of a new owner. Besides the human-readable audit
43	     * line (capturing its id, member id, registration date and membership level), an
44	     * immutable {@link OwnerCreatedEvent} carrying the owner's current primary identifier
45	     * is emitted as JSON on the same trail.
46	     */
47	    public void logCreated(Owner owner) {
48	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
49	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
50	            owner.getMembershipLevel());
51	        OwnerCreatedEvent event = new OwnerCreatedEvent(sequence.incrementAndGet(),
52	            owner.getId(), owner.getPrimaryIdentifier(), owner.getMembershipLevel());
53	        AUDIT.info(objectMapper.writeValueAsString(event));
54	    }
55	}
