458	    /**
459	     * The owner's identity key: the single derived value used to detect duplicate owners,
460	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + (email or empty) + '|' +
461	     * soundex(lastName)} (see {@link Soundex}). Two owners are hard duplicates only when
462	     * their identity keys are equal; because the telephone is part of the key, members of
463	     * one household with different telephones stay distinct. Derived from the owner's own
464	     * fields, so it stays consistent with them.
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        String telephonePart = this.telephone == null ? "" : this.telephone;
469	        String emailPart = this.email == null ? "" : this.email;
470	        return Sha256.hex(telephonePart + "|" + emailPart + "|" + Soundex.of(this.getLastName()));
471	    }
472	
473	    /**
474	     * The owner's age band relative to their registration date: {@code "MINOR"} when
475	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
476	     * Derived from the owner's own birth and registration dates, so it stays consistent
477	     * with them; null until a birth date is on file. See {@link AgeBand}.
478	     */
479	    @Transient
480	    public String getAgeBand() {
481	        if (this.birthDate == null || this.registrationDate == null) {
482	            return null;
483	        }
484	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
485	    }
486	
487	    /**
488	     * Whether this owner warrants a manual review: {@code true} when any risk signal holds,
489	     * namely when it is a {@link #getPossibleDuplicate() possible duplicate}, its email
490	     * domain is disposable-adjacent (see {@link DisposableEmailDomains}), or its city was
491	     * over its soft capacity when it was created (see {@link #getCapacityWarning()});
492	     * otherwise {@code false}. Derived from the owner's own fields, so it stays consistent
493	     * with them.
494	     */
495	    @Transient
496	    public Boolean getRiskFlag() {
497	        return Boolean.TRUE.equals(this.possibleDuplicate)
498	            || Boolean.TRUE.equals(this.capacityWarning)
499	            || DisposableEmailDomains.isDisposableAdjacent(this.email);
500	    }
