502	    /**
503	     * Normalize the registration date before persisting: default it to the server's
504	     * current date when none was supplied, then roll it forward onto a business day so
505	     * every newly persisted owner is registered on a weekday.
506	     */
507	    @PrePersist
508	    void normalizeRegistrationDate() {
509	        if (this.registrationDate == null) {
510	            this.registrationDate = LocalDate.now();
511	        }
512	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
513	    }
