21	/**
22	 * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by
23	 * the calendar year in which it begins, so a date on or after 1 July belongs to that
24	 * year's fiscal year and an earlier date belongs to the previous one. This is the single
25	 * source of truth for turning a date into a fiscal year, so callers never repeat it.
26	 */
27	public final class FiscalYear {
28	
29	    /** The month a fiscal year starts on: 1 July. */
30	    static final Month START_MONTH = Month.JULY;
31	
32	    private FiscalYear() {
33	    }
34	
35	    /**
36	     * The calendar year in which the fiscal year containing {@code date} begins.
37	     */
38	    public static int startingYearOf(LocalDate date) {
39	        return date.getMonthValue() >= START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
40	    }
41	
42	    /**
43	     * The last two digits of the fiscal year's starting calendar year, used as the year
44	     * segment of date-derived identifiers.
45	     */
46	    public static int shortYearOf(LocalDate date) {
47	        return startingYearOf(date) % 100;
48	    }
49	
50	    /**
51	     * The fiscal-year label for {@code date}, formatted {@code 'FY<YY>'} where YY is the
52	     * last two digits of the fiscal year's starting calendar year (e.g. {@code "FY26"}).
53	     */
54	    public static String labelFor(LocalDate date) {
55	        return String.format("FY%02d", shortYearOf(date));
56	    }
57	
58	    /**
59	     * The number of whole fiscal years elapsed from {@code from} to {@code to}, i.e. how
60	     * many 1-July boundaries the interval crosses.
61	     */
62	    public static int elapsedBetween(LocalDate from, LocalDate to) {
63	        return startingYearOf(to) - startingYearOf(from);
64	    }
65	}
