16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Locale;
19	
20	/**
21	 * The American Soundex phonetic algorithm.
22	 *
23	 * <p>Encodes a word as a letter followed by three digits (e.g. {@code "Robert"} and
24	 * {@code "Rupert"} both encode to {@code "R163"}), so that names that sound alike share
25	 * a code. This is the single source of truth for that computation, so callers never
26	 * repeat it.
27	 */
28	public final class Soundex {
29	
30	    private static final String EMPTY_CODE = "0000";
31	
32	    private static final int CODE_LENGTH = 4;
33	
34	    private Soundex() {
35	    }
36	
37	    /**
38	     * Compute the four-character Soundex code of {@code value}. Non-letters are ignored;
39	     * a value with no letters encodes to {@code "0000"}.
40	     *
41	     * @param value the word to encode, e.g. a last name
42	     * @return the Soundex code: an upper-case initial letter and three digits
43	     */
44	    public static String of(String value) {
45	        String letters = value == null ? "" : value.replaceAll("[^A-Za-z]", "").toUpperCase(Locale.ROOT);
46	        if (letters.isEmpty()) {
47	            return EMPTY_CODE;
48	        }
49	        StringBuilder code = new StringBuilder(CODE_LENGTH).append(letters.charAt(0));
50	        int previous = codeOf(letters.charAt(0));
51	        for (int i = 1; i < letters.length() && code.length() < CODE_LENGTH; i++) {
52	            char letter = letters.charAt(i);
53	            // 'H' and 'W' are transparent: they neither contribute a digit nor separate
54	            // two like-coded consonants, so the previous code carries across them.
55	            if (letter == 'H' || letter == 'W') {
56	                continue;
57	            }
58	            int digit = codeOf(letter);
59	            if (digit != 0 && digit != previous) {
60	                code.append((char) ('0' + digit));
61	            }
62	            // Vowels (code 0) reset the running code so a repeated consonant that is
63	            // separated by a vowel is encoded again; consonants set it to their own code.
64	            previous = digit;
65	        }
66	        while (code.length() < CODE_LENGTH) {
67	            code.append('0');
68	        }
69	        return code.toString();
70	    }
71	
72	    /**
73	     * The Soundex digit for a single upper-case letter: 0 for vowels and the transparent
74	     * letters (A, E, I, O, U, Y, H, W), and 1-6 for the six consonant groups.
75	     */
76	    private static int codeOf(char letter) {
77	        switch (letter) {
78	            case 'B': case 'F': case 'P': case 'V':
79	                return 1;
80	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
81	                return 2;
82	            case 'D': case 'T':
83	                return 3;
84	            case 'L':
85	                return 4;
86	            case 'M': case 'N':
87	                return 5;
88	            case 'R':
89	                return 6;
90	            default:
91	                return 0;
92	        }
93	    }
94	}
