185	    public LocalDate getBirthDate() {
186	        return this.birthDate;
187	    }
188	
189	    public void setBirthDate(LocalDate birthDate) {
190	        this.birthDate = birthDate;
191	    }
192	
193	    public String getMemberId() {
194	        return this.memberId;
195	    }
196	
197	    public void setMemberId(String memberId) {
198	        this.memberId = memberId;
199	    }
200	
201	    /**
202	     * The owner's primary identifier: the single value that identifies the owner across
203	     * the system, its {@link #getMemberId() member id}. Callers that need "the owner's
204	     * identity" (such as the audit trail) should read this rather than the member id
205	     * directly, so the identifier is sourced in one place.
206	     */
207	    @Transient
208	    public String getPrimaryIdentifier() {
209	        return this.memberId;
210	    }
211	
212	    public String getHouseholdId() {
