230	    }
231	
232	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
233	        this.bulkSignupWarning = bulkSignupWarning;
234	    }
235	
236	    /**
237	     * Whether this owner's city already held enough owners, when this owner was created,
238	     * to be approaching its hard capacity limit (between 40 and 49 owners, one short of
239	     * the limit of 50). Stamped at creation, it flags a city filling towards capacity.
240	     */
