263	    }
264	
265	    /**
266	     * Whether this owner deliberately declared, when created, that it shares its
267	     * household with an existing owner (the request's {@code sharesHousehold} flag).
268	     * A declared member is created despite occupying an existing household and is not
269	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
270	     */
271	    @Transient
272	    public boolean isDeclaredHouseholdMember() {
273	        return this.declaredHouseholdMember;
274	    }
275	
276	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
277	        this.declaredHouseholdMember = declaredHouseholdMember;
278	    }
279	
280	    /**
281	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
282	     * existing owner: not a hard duplicate, but sharing that owner's phonetic last name
283	     * (see {@link Soundex}) and postcode while its {@link #getIdentityKey() identity key}
284	     * differs. See {@link #getPossibleDuplicateOf()}.
285	     */
286	    public Boolean getPossibleDuplicate() {
287	        return this.possibleDuplicate;
288	    }
289	
290	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
291	        this.possibleDuplicate = possibleDuplicate;
292	    }
293	
294	    /**
295	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
296	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
297	     */
298	    public Integer getPossibleDuplicateOf() {
299	        return this.possibleDuplicateOf;
300	    }
301	
302	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
303	        this.possibleDuplicateOf = possibleDuplicateOf;
304	    }
305	
306	    /**
307	     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
308	     * deleting the owner retains its row and flags it {@code true}. A deleted owner is
309	     * still retrievable but is ignored by the create endpoint's duplicate/identity checks.
310	     */
311	    public boolean isDeleted() {
312	        return this.deleted;
313	    }
314	
315	    public void setDeleted(boolean deleted) {
316	        this.deleted = deleted;
317	    }
318	
319	    /**
320	     * The ceiling on this owner's {@link #getMembershipLevel() membership level}, stamped
321	     * when the owner is created as one above the highest membership level then held by an
322	     * existing member of its household, or null when the owner had no existing household
323	     * member and so is subject to no ceiling. See {@link #getMembershipLevel()}.
324	     */
325	    public Integer getMembershipLevelCap() {
326	        return this.membershipLevelCap;
327	    }
328	
329	    public void setMembershipLevelCap(Integer membershipLevelCap) {
330	        this.membershipLevelCap = membershipLevelCap;
331	    }
332	
333	    /**
334	     * The owner's fiscal year: the {@code 'FY<YY>'} label of the fiscal year carried by
335	     * their {@link #getMemberId() member id}, so the fiscal year stays consistent with the
336	     * owner's identity (see {@link FiscalYear}). Until a member id has been assigned it
337	     * falls back to the fiscal year of the owner's business-day-adjusted registration
338	     * date, the same value the member id itself is built from; null until then.
339	     */
340	    @Transient
341	    public String getFiscalYear() {
342	        if (this.memberId != null) {
343	            return String.format("FY%02d", MemberId.fiscalYearShortOf(this.memberId));
344	        }
345	        if (this.registrationDate == null) {
346	            return null;
347	        }
348	        return FiscalYear.labelFor(this.registrationDate);
349	    }
350	
351	    /**
352	     * The owner's membership points, starting at zero: two points are added when an email is
353	     * on file, one more when the owner is unique (namesake count of zero), two more for a
354	     * household of three or more, and three more when the owner has accrued more than a fiscal
355	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
356	     * consistent with them.
357	     */
358	    @Transient
359	    public Integer getMembershipPoints() {
360	        int points = 0;
361	        boolean hasEmail = this.email != null && !this.email.isEmpty();
362	        if (hasEmail) {
363	            points += 2;
364	        }
365	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
366	        if (unique) {
367	            points += 1;
368	        }
369	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
370	        if (largeHousehold) {
371	            points += 2;
372	        }
373	        boolean tenured = this.registrationDate != null
374	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
375	        if (tenured) {
376	            points += 3;
377	        }
378	        return points;
379	    }
380	
381	    /**
382	     * The owner's membership level, a number from 1 to 4, derived from their
383	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}), then
384	     * held down to its {@link #getMembershipLevelCap() household ceiling} when one applies.
385	     * Derived from the owner's own fields, so it stays consistent with them.
386	     */
387	    @Transient
388	    public Integer getMembershipLevel() {
389	        int level = MembershipLevel.forPoints(getMembershipPoints());
390	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
391	            return this.membershipLevelCap;
392	        }
393	        return level;
394	    }
395	
396	    /**
397	     * The owner's locality: the canonical region, taken as the region segment of the
398	     * {@link #getMemberId() member id} (formatted {@code '<REGION><FY><HASH8><CHK>'}), so
399	     * the locality stays consistent with the owner's identity. When no member id has been
400	     * assigned yet it falls back to resolving the region directly from the postcode and
401	     * city (see {@link RegionResolver}), the same rule the member id itself is built from.
402	     */
403	    @Transient
404	    public String getLocality() {
405	        if (this.memberId != null) {
406	            String region = MemberId.regionOf(this.memberId);
407	            if (!region.isEmpty()) {
408	                return region;
409	            }
410	        }
411	        return RegionResolver.regionFor(this.postcode, this.city);
412	    }
413	
414	    /**
415	     * The owner's marketing segment, formatted {@code '<TIER>_<AREA>'} (see
416	     * {@link OwnerSegment}): the tier from their {@link #getMembershipLevel() membership
417	     * level} and the area from whether their {@link #getLocality() locality} is a known
418	     * region. Derived from the owner's own fields, so it stays consistent with them.
419	     */
420	    @Transient
421	    public String getOwnerSegment() {
422	        return OwnerSegment.of(getMembershipLevel(), getLocality());
423	    }
424	
425	    /**
426	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
427	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
428	     * stays consistent with the owner's region. Null when the locality has no known timezone.
429	     */
430	    @Transient
431	    public String getTimezone() {
432	        return RegionTimezoneTable.timezoneFor(getLocality());
433	    }
434	
435	    /**
436	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
437	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
438	     * stays consistent with them.
439	     */
440	    @Transient
441	    public String getContactPreference() {
442	        boolean hasEmail = this.email != null && !this.email.isEmpty();
443	        return hasEmail ? "EMAIL" : "PHONE";
444	    }
445	
446	    /**
447	     * The owner's telephone formatted for human display: the stored E.164 number
448	     * rendered as its country calling code, a space and the national digits grouped
449	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
450	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
451	     * consistent with it. See {@link TelephoneFormatter}.
452	     */
453	    @Transient
454	    public String getTelephoneDisplay() {
