551	    /**
552	     * Return the Pet with the given name, or null if none found for this Owner.
553	     *
554	     * @param name to test
555	     * @return true if pet name is already in use
556	     */
557	    public Pet getPet(String name, boolean ignoreNew) {
558	        name = name.toLowerCase();
559	        for (Pet pet : getPetsInternal()) {
560	            if (!ignoreNew || !pet.isNew()) {
561	                String compName = pet.getName();
562	                compName = compName.toLowerCase();
563	                if (compName.equals(name)) {
