22	/**
23	 * Computes the SHA-256 digest of a string as lower-case hexadecimal. Shared by the
24	 * owner identity derivations so the hashing is written in exactly one place.
25	 */
26	public final class Sha256 {
27	
28	    private Sha256() {
29	    }
30	
31	    /**
